'use client';

import { useActionState } from 'react';

type ContactFormState = {
  message: string;
  success?: boolean;
};

const initialState: ContactFormState = {
  message: '',
};

function ContactFormFields({
  submitAction,
}: {
  submitAction: (
    prevState: ContactFormState,
    formData: FormData
  ) => Promise<ContactFormState>;
}) {
  const [state, formAction, pending] = useActionState(submitAction, initialState);

  return (
    <div>
      <h2>Contact Us</h2>
      <form action={formAction}>
        <div>
          <label htmlFor="name">Name</label>
          <input
            id="name"
            name="name"
            type="text"
            placeholder="Your name"
            required
          />
        </div>
        <div>
          <label htmlFor="email">Email</label>
          <input
            id="email"
            name="email"
            type="email"
            placeholder="your@email.com"
            required
          />
        </div>
        <div>
          <label htmlFor="message">Message</label>
          <textarea
            id="message"
            name="message"
            rows={5}
            placeholder="Your message"
            required
          />
        </div>
        {state.message && (
          <p aria-live="polite" style={{ color: state.success ? 'green' : 'red' }}>
            {state.message}
          </p>
        )}
        <button type="submit" disabled={pending}>
          {pending ? 'Sending...' : 'Send Message'}
        </button>
      </form>
    </div>
  );
}

export default function ContactForm() {
  async function submitContact(
    _prevState: ContactFormState,
    formData: FormData
  ): Promise<ContactFormState> {
    'use server';

    const name = formData.get('name');
    const email = formData.get('email');
    const message = formData.get('message');

    // JavaScript validation - check that all fields are provided
    if (!name || typeof name !== 'string' || !name.trim()) {
      return { message: 'Name is required.' };
    }
    if (!email || typeof email !== 'string' || !email.trim()) {
      return { message: 'Email is required.' };
    }
    if (!message || typeof message !== 'string' || !message.trim()) {
      return { message: 'Message is required.' };
    }

    // In a real app, you would save the contact message to a database
    console.log('Contact message received:', {
      name: name.trim(),
      email: email.trim(),
      message: message.trim(),
    });

    return {
      message: 'Thank you! Your message has been sent.',
      success: true,
    };
  }

  return <ContactFormFields submitAction={submitContact} />;
}

